236	    @Override
237	    @Transactional
238	    public void saveOwner(Owner owner) throws DataAccessException {
239	        if (owner.isNew() && ownerRepository.existsByTelephone(owner.getTelephone())) {
240	            throw new DuplicateTelephoneException(owner.getTelephone());
241	        }
242	        if (owner.isNew()) {
243	            List<Owner> householdMembers = findHouseholdMembers(owner);
244	            if (!householdMembers.isEmpty()) {
245	                if (!owner.isSharesHousehold()) {
246	                    throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
247	                }
248	                owner.setHouseholdId(resolveHouseholdId(householdMembers));
249	            }
250	        }
251	        if (owner.getRegistrationDate() == null) {
252	            owner.setRegistrationDate(LocalDate.now());
253	        }
254	        if (owner.isNew() && owner.getCustomerCode() == null) {
255	            owner.setCustomerCode(generateCustomerCode(owner));
256	        }
257	        ownerRepository.save(owner);
258	
259	    }
260	
261	    /**
262	     * Find the owners that already belong to the same household as {@code owner}, i.e. have the same
263	     * last name and the same address. Last names are compared case-insensitively with collapsed
264	     * whitespace; addresses are compared in their canonical normalized form (see
265	     * {@link AddressNormalizer}), so differences in letter case, runs of spaces or street-type
266	     * abbreviations are ignored. Returns an empty list when the owner has no last name or address to
267	     * match on.
268	     */
269	    private List<Owner> findHouseholdMembers(Owner owner) {
270	        String lastName = normalizeHouseholdKey(owner.getLastName());
271	        String address = AddressNormalizer.normalize(owner.getAddress());
272	        if (lastName == null || address == null) {
273	            return List.of();
274	        }
275	        return ownerRepository.findAll().stream()
276	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
277	                && address.equals(AddressNormalizer.normalize(existing.getAddress())))
278	            .toList();
279	    }
280	
281	    /**
282	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
283	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
284	     * new one is generated. The resolved value is back-filled onto every member that is missing it
285	     * (or has a different one) so all members of the household share the same identifier.
286	     */
287	    private String resolveHouseholdId(List<Owner> members) {
288	        String householdId = members.stream()
289	            .map(Owner::getHouseholdId)
290	            .filter(id -> id != null && !id.isBlank())
291	            .findFirst()
292	            .orElseGet(() -> UUID.randomUUID().toString());
293	        for (Owner member : members) {
294	            if (!householdId.equals(member.getHouseholdId())) {
295	                member.setHouseholdId(householdId);
296	                ownerRepository.save(member);
297	            }
298	        }
299	        return householdId;
300	    }
301	
302	    /**
303	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
304	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
305	     */
306	    private String normalizeHouseholdKey(String value) {
307	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
308	    }
309	
310	    /**
311	     * Build an owner's {@code customerCode} as {@code '<LAST3>-<NNNN>'}: LAST3 is the
312	     * upper-cased first three letters of the owner's last name, and NNNN is a global
313	     * 4-digit zero-padded sequence equal to one more than the current number of owners
314	     * (e.g. {@code 'SMI-0007'}).
315	     */
316	    private String generateCustomerCode(Owner owner) {
317	        String lastName = owner.getLastName();
318	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
319	        long sequence = ownerRepository.findAll().size() + 1L;
320	        return String.format("%s-%04d", last3, sequence);
321	    }
322	
